  def up do
    execute("SET statement_timeout = '10min'")
    
    Logger.info("======================================")
    Logger.info("Starting Bayern schools import...")
    Logger.info("Total schools in data: #{length(@schools_data)}")
    Logger.info("Process limit: #{inspect(@process_limit)}")
    Logger.info("======================================\n")
    
    # Get Bayern federal state
    bayern = Repo.get_by!(Location, name: "Bayern", is_federal_state: true)
    
    # Determine how many schools to process
    schools_to_process = case @process_limit do
      nil -> @schools_data
      limit -> Enum.take(@schools_data, limit)
    end
    
    Logger.info("Processing #{length(schools_to_process)} schools...\n")
    
    # Track statistics
    results = %{updated: 0, created: 0, errors: 0}
    
    # Process each school
    results = Enum.reduce(schools_to_process, results, fn school_data, acc ->
      Logger.info("\n--- Processing: #{school_data.name} ---")
      Logger.info("Schulnummer: #{school_data.schulnummer}, PLZ: #{school_data.plz}")
      
      case find_existing_school(school_data) do
        {:found, school, address} ->
          Logger.info("✓ Found existing school: #{school.name} (ID: #{school.id})")
          update_existing_school(school, address, school_data)
          Map.update!(acc, :updated, &(&1 + 1))
          
        :not_found ->
          Logger.info("→ School not found, creating new...")
          case create_new_school(bayern, school_data) do
            :ok -> Map.update!(acc, :created, &(&1 + 1))
            :error -> Map.update!(acc, :errors, &(&1 + 1))
          end
      end
    end)
    
    # Log final summary
    Logger.info("\n======================================")
    Logger.info("Bayern schools import completed at: #{DateTime.utc_now() |> DateTime.to_iso8601()}")
    Logger.info("Summary:")
    Logger.info("  - Updated: #{results.updated} schools")
    Logger.info("  - Created: #{results.created} schools")
    Logger.info("  - Errors: #{results.errors} schools")
    Logger.info("======================================")
    
    if @process_limit do
      remaining = length(@schools_data) - length(schools_to_process)
      if remaining > 0 do
        Logger.warning("\n⚠️  #{remaining} schools were not processed due to limit.")
        Logger.warning("    Change @process_limit to nil to process all schools.")
      end
    end
  end

  def down do
    # This migration is not easily reversible
