    Logger.warning("Rollback not implemented for Bayern schools import")
  end
  
  defp find_existing_school(school_data) do
    query = from a in Address,
      join: l in Location, on: l.id == a.school_location_id,
      where: a.zip_code == ^school_data.plz and
             (a.official_id == ^school_data.schulnummer or
              fragment("? LIKE ?", l.name, ^("%" <> school_data.schulnummer <> "%"))),
      select: {l, a},
      limit: 1
      
    case Repo.one(query) do
      {school, address} -> {:found, school, address}
      nil -> :not_found
    end
  end
  
  defp update_existing_school(_school, address, school_data) do
    changes = []
    
    # Check phone number changes
    changes = if address.phone_number != school_data.telefon do
      Logger.info("  Phone: #{inspect(address.phone_number)} → #{inspect(school_data.telefon)}")
      [{:phone_number, school_data.telefon} | changes]
    else
      changes
    end
    
    # Check homepage URL changes
    changes = if address.homepage_url != school_data.homepage do
      Logger.info("  Homepage: #{inspect(address.homepage_url)} → #{inspect(school_data.homepage)}")
      [{:homepage_url, school_data.homepage} | changes]
    else
      changes
    end
    
    if length(changes) > 0 do
      # Use Ecto directly to avoid the update_attrs function
      update_attrs = Enum.into(changes, %{})
      
      case address
           |> Ecto.Changeset.change(update_attrs)
           |> Repo.update() do
        {:ok, _} -> 
          Logger.info("✓ Successfully updated school")
        {:error, changeset} ->
          Logger.error("✗ Failed to update address: #{inspect(changeset.errors)}")
      end
    else
      Logger.info("  No changes needed")
    end
  end
  
  defp create_new_school(bayern, school_data) do
    # Find or create city
    city = find_or_create_city(bayern, school_data.ort, school_data.plz)
    
    # Create school
    school_attrs = %{
      name: school_data.name,
      parent_location_id: city.id,
      is_school: true,
      cachable_calendar_location_id: bayern.id
    }
    
    case Locations.create_location(school_attrs) do
      {:ok, school} ->
        Logger.info("✓ Created school: #{school.name} (ID: #{school.id})")
        
        # Create address
        address_attrs = %{
          school_location_id: school.id,
          street: school_data.strasse,
          zip_code: school_data.plz,
          city: school_data.ort,
          phone_number: school_data.telefon,
          homepage_url: school_data.homepage,
          school_type: school_data.schultyp,
          official_id: school_data.schulnummer
        }
        
        # Use Ecto directly to avoid the update_attrs function in Address changeset
        %Address{}
        |> Ecto.Changeset.cast(address_attrs, [:school_location_id, :street, :zip_code, :city, :phone_number, :homepage_url, :school_type, :official_id])
        |> Ecto.Changeset.validate_required([:school_location_id])
        |> Repo.insert()
        |> case do
          {:ok, _address} ->
            Logger.info("✓ Created address for school")
            :ok
          {:error, changeset} ->
            Logger.error("✗ Failed to create address: #{inspect(changeset.errors)}")
            :error
        end
        
      {:error, changeset} ->
        Logger.error("✗ Failed to create school: #{inspect(changeset.errors)}")
        :error
    end
  end
  
  defp find_or_create_city(bayern, city_name, zip_code) do
    # Try to find city by name and zip code
    query = from c in Location,
      join: zcm in ZipCodeMapping, on: zcm.location_id == c.id,
      join: zc in ZipCode, on: zc.id == zcm.zip_code_id,
      where: c.is_city == true and c.name == ^city_name and zc.value == ^zip_code,
      limit: 1
    
    case Repo.one(query) do
      nil ->
        Logger.info("  Creating city: #{city_name} (#{zip_code})")
        
        # Find or create county
        county = find_or_create_county_for_city(bayern, city_name)
        
        city_attrs = %{
          name: city_name,
          parent_location_id: county.id,
          is_city: true,
          cachable_calendar_location_id: bayern.id
        }
        
        {:ok, city} = Locations.create_location(city_attrs)
        
        # Create or find zip code and map it
        zip_code_record = case Repo.get_by(ZipCode, value: zip_code) do
          nil -> 
            # Get Germany location
            germany = Repo.get_by!(Location, name: "Deutschland", is_country: true)
            {:ok, zc} = Maps.create_zip_code(%{value: zip_code, country_location_id: germany.id})
            zc
          existing -> existing
        end
        
        Maps.create_zip_code_mapping(%{
          zip_code_id: zip_code_record.id,
          location_id: city.id
        })
        
        city
        
      city -> 
        city
    end
  end
  
  defp find_or_create_county_for_city(bayern, _city_name) do
    # This is a simplified version - in production you'd need proper city->county mapping
    county_name = "Städte ohne Landkreiszuordnung"
    
    case Repo.get_by(Location, name: county_name, parent_location_id: bayern.id, is_county: true) do
      nil ->
        county_attrs = %{
          name: county_name,
          parent_location_id: bayern.id,
          is_county: true,
          cachable_calendar_location_id: bayern.id
        }
        {:ok, county} = Locations.create_location(county_attrs)
        county
        
      county -> county
    end
  end
